// Debug the HTTP response
const items = $input.all();

console.log('=== DEBUG HTTP RESPONSE ===');
console.log('Number of items:', items.length);

if (items.length > 0) {
  const item = items[0];
  console.log('Response structure:');
  console.log('- json:', typeof item.json);
  console.log('- binary:', typeof item.binary);
  console.log('- headers:', typeof item.headers);
  console.log('- statusCode:', item.statusCode);

  if (item.json) {
    console.log('JSON data type:', Array.isArray(item.json) ? 'array' : typeof item.json);
    console.log('JSON length:', Array.isArray(item.json) ? item.json.length : 'N/A');

    if (Array.isArray(item.json) && item.json.length > 0) {
      const firstItem = item.json[0];
      console.log('First item keys:', Object.keys(firstItem));
      console.log('First item status:', firstItem.status);
      console.log('First item tenant_info:', !!firstItem.tenant_info);
      console.log('First item units:', !!firstItem.units);
    }
  }

  if (item.headers) {
    console.log('Response headers:', item.headers);
  }

  if (item.statusCode) {
    console.log('Status code:', item.statusCode);
  }
} else {
  console.log('No items received');
}

console.log('=== END DEBUG ===');

return items;
